Please note that this applet only works in modern browsers that support HTML5 canvas element.

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title> Pendulum Simulator </title>
    <style>
        #canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <h1>Pendulum Simulator</h1>
    <input id="initialAngle" type="number" value="60" min="0" max="180" step="1"> degrees <br>
    <button id="release-button">Release Pendulum</button>
    <canvas id="pendulum-canvas" width="600" height="400"></canvas>

    <script>
        let canvas = document.getElementById('pendulum-canvas');
        let ctx = canvas.getContext('2d');
        let initialAngle = 60;
        let gravity = 0.2;
        let friction = 0.01;
        let angle = initialAngle;
        let anglVelocity = 0;
        let anglAcceleration = 0;
        let timer = null;

        document.getElementById('release-button').addEventListener('click', releasePendulum);

        function releasePendulum() {
            initialAngle = parseInt(document.getElementById('initialAngle').value);
            angle = initialAngle;
            anglVelocity = 0;
            anglAcceleration = -gravity * Math.sin(Math.PI / 180 * angle);
            timer = setInterval(updatePendulum, 16); // update 16 times per second
        }

        function updatePendulum() {
            anglAcceleration += -gravity * Math.sin(Math.PI / 180 * angle) - friction * anglVelocity;
            anglVelocity +=anglAcceleration;
            angle += anglVelocity;
            anglAcceleration = -gravity * Math.sin(Math.PI / 180 * angle) - friction * anglVelocity;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, 100, -Math.PI / 2, Math.PI / 2 - Math.PI / 180 * angle);
            ctx.stroke();
            if (Math.abs(anglVelocity) < 0.01) {
                clearInterval(timer);
                console.log("Pendulum stopped");
            }
        }
    </script>
</body>
</html>
```

